import pytest

from ansible.utils.unsafe_proxy import AnsibleUnsafeText, wrap_var


def test_wrap_var_wraps_set_members():
    original = {"first", "second"}

    wrapped = wrap_var(original)

    assert type(wrapped) is set
    assert wrapped is not original
    assert wrapped == {AnsibleUnsafeText("first"), AnsibleUnsafeText("second")}
    assert all(type(item) is AnsibleUnsafeText for item in wrapped)
    assert original == {"first", "second"}
